// Typed access to the design-system data in this folder. The JSON files are generated by
// scripts/extract-assets.mjs and carry the design-system artifact version they came from.
import palette from "./palette.json";
import sprites from "./sprites.json";
import features from "./features.json";
import lattice from "./lattice.json";
import nodeTones from "./node-tones.json";

export interface AssetHeader {
  generatedBy: string;
  source: string;
  sourceVersion: string;
}

export const paletteAsset = palette as AssetHeader & { colours: Record<string, string> };
export const spritesAsset = sprites as AssetHeader & {
  palette: Record<string, string>;
  sprites: Record<string, string[]>;
};
export const featuresAsset = features as AssetHeader & {
  bitmaps: Record<string, string[] | null>;
  colours: Record<string, string>;
};
export const latticeAsset = lattice as AssetHeader & {
  tileWidth: number;
  tileHeight: number;
  rowStep: number;
  oddRowShift: number;
  seed: { col: number; row: number; add: number };
  terrainLegend: Record<string, string>;
  featureLegend: Record<string, string>;
};

export const nodeTonesAsset = nodeTones as AssetHeader & { tones: Record<string, { stroke: string; fill: string }> };
